import React, { useEffect, useState } from 'react'
import { useLocation, useNavigate } from 'react-router-dom'
import { Tabs, Tab, Box, useMediaQuery, useTheme } from '@mui/material'
import UserPage from '../ListingPage'
import DraftedListing from './DraftedListing'

const tabMap = {
  published: 0,
  drafted: 1,
}
const tabKeys = ['published', 'drafted']

const ListingTabs = () => {
  const location = useLocation()
  const navigate = useNavigate()
  const theme = useTheme()
  const isMobile = useMediaQuery(theme.breakpoints.down('sm'))

  const searchParams = new URLSearchParams(location.search)
  const currentTab = searchParams.get('tab') || 'published'

  const [tabValue, setTabValue] = useState(tabMap[currentTab] || 0)

  useEffect(() => {
    // Sync tab state with URL when location changes
    const tabFromUrl = searchParams.get('tab')
    if (tabFromUrl && tabMap[tabFromUrl] !== undefined) {
      setTabValue(tabMap[tabFromUrl])
    }
  }, [location.search])

  const handleChange = (event, newValue) => {
    const selectedTab = tabKeys[newValue]
    setTabValue(newValue)
    searchParams.set('tab', selectedTab)
    navigate(`${location.pathname}?${searchParams.toString()}`, { replace: true })
  }

  return (
    <Box>
      <Tabs
        value={tabValue}
        onChange={handleChange}
        variant={isMobile ? 'scrollable' : 'standard'}
        scrollButtons={isMobile ? 'auto' : false}
        aria-label="listing tabs"
        textColor="primary"
        indicatorColor="primary"
        sx={{
          borderBottom: 1,
          borderColor: 'divider',
          mb: 2,
        }}
      >
        <Tab label="Published Listings" />
        <Tab label="Drafted Listings" />
      </Tabs>

      <Box>
        {tabValue === 0 && <UserPage />}
        {tabValue === 1 && <DraftedListing />}
      </Box>
    </Box>
  )
}

export default ListingTabs