/* eslint-disable react/prop-types */
import React, { useEffect, useState, useMemo } from 'react';
import { Helmet } from 'react-helmet-async';
import { useNavigate, useLocation } from 'react-router-dom';
import {
  Card,
  Table,
  Stack,
  Paper,
  Button,
  Popover,
  Checkbox,
  TableRow,
  MenuItem,
  TableBody,
  TableCell,
  Typography,
  IconButton,
  TableContainer,
  TablePagination,
  Grid,
  Modal,
  Box,
  Menu,
  Select,
  Badge,
} from '@mui/material';
import MoreVertIcon from '@mui/icons-material/MoreVert';
import Decline from '../components/icons/Decline';
import { axios } from '../utils/axios';
import { IMAGE_URL, APP_URL } from '../utils/config';
import { updateUrlParams } from '../utils/urlUtilis';
// components
import Label from '../components/label';
import Iconify from '../components/iconify';
import Scrollbar from '../components/scrollbar';
// sections
import { UserListHead, UserListToolbar } from '../sections/@dashboard/user';
import "./page.scss"
import { useMyContext } from './provider';
import GenerateToastConfig from '../components/toast-config/GenerateToastConfig';
import useResponsive from '../hooks/useResponsive';
import DeleteModal from '../components/deleteModal/DeleteModal';
import InputField from '../components/input/inputField';
import TanstackTable from '../components/tanstackMUItable/TanstackTable';
import TanstackTableV8 from '../components/tanstackMUItable/tanstackTableV8';

export default function UserPage() {
  const location = useLocation();
  const queryParams = new URLSearchParams(location.search)

  const navigate = useNavigate();
  const [search, setsearch] = useState('');
  const [open, setOpen] = useState(false);
  const [opens, setOpens] = useState(false);
  const [openApprove, setOpenApprove] = useState(false);
  const [open2, setOpen2] = useState(false);
  const [open3, setOpen3] = useState(false);
  const [page, setPage] = useState(parseInt(queryParams.get('page'), 10) || 1);
  const [order, setOrder] = useState('asc');
  const [selected, setSelected] = useState([]);
  const [orderBy, setOrderBy] = useState('name');
  const [filterName, setFilterName] = useState('');
  const [rowsPerPage, setRowsPerPage] = useState(parseInt(queryParams.get('limit'), 10) || 10);
  const [userList, setUserList] = useState([]);
  const [getAmenities, setGetAmenities] = useState([]);
  const [totalCount, setTotalCount] = useState('');
  const [bedRoom, setBedRoom] = useState(0);
  const [bathRoom, setBathRoom] = useState(0);
  const [filterbathRoom, setFilterBathRoom] = useState(0);
  const [filterbedRoom, setFilterBedRoom] = useState(0);
  const [reason, setReason] = useState('');
  const [selectedName, setSelectedName] = useState([]);
  const [selectedStatus, setSelectedStatus] = useState('');
  const [filterStatus, setFilterStatus] = useState('');
  const [filterAmenity, setFilterAmenity] = useState([]);
  const [rowId, setRowId] = useState('')
  const [userId, setUserId] = useState('')
  const [addListing, setAddListing] = useState(false)
  const [userOptions, setUserOptions] = useState([]);
  const [title, setTitle] = useState("")
  const [title2, setTitle2] = useState("")
  const [userId1, setUserId1] = useState('')
  const { i18 } = useMyContext();
  const isMobile = useResponsive('down', 'sm')
  const [anchorEl, setAnchorEl] = useState(null);
  const [filters, setFilters] = useState({});
  const [isLoading, setIsLoading] = useState(true);


  const style11 = {
    position: 'absolute',
    top: '50%',
    left: '50%',
    transform: 'translate(-50%, -50%)',
    width: isMobile ? "90%" : 600,
    backgroundColor: 'white',
    borderRadius: '8px',
    boxShadow: '0px 4px 16px rgba(0, 0, 0, 0.2)',
    p: isMobile ? 2 : 4,
  };

  const handleMenuOpen = (event) => {
    setAnchorEl(event.currentTarget);
  };

  const handleMenuClose = () => {
    setAnchorEl(null);
  };

  const TABLE_HEAD = [
    { id: 'propertyName', label: i18?.LISTINGPAGE?.PROPERTY_NAME || 'Property Name', alignRight: false },
    { id: 'userName', label: i18?.LISTINGPAGE?.USER_NAME || 'User Name', alignRight: false },
    { id: 'city', label: i18?.LISTINGPAGE?.CITY || 'City', alignRight: false },
    { id: 'state', label: i18?.LISTINGPAGE?.STATE || 'State', alignRight: false },
    { id: 'country', label: i18?.LISTINGPAGE?.COUNTRY || 'Country', alignRight: false },
    { id: 'commission&tax', label: i18?.LISTINGPAGE?.COMMISSION_TAX || 'Commission & Tax', alignRight: false },
    { id: 'publish', label: i18?.LISTINGPAGE?.PUBLISH || 'Publish', alignRight: false },
    { id: 'status', label: i18?.LISTINGPAGE?.STATUS || 'Status', alignRight: false },
    { id: 'view', label: i18?.LISTINGPAGE?.VIEW || 'View', alignRight: false },
    { id: 'action', label: i18?.LISTINGPAGE?.ACTION || 'Action', alignRight: false },
  ];


  // newValue

  const verifiedUser = async () => {
    try {
      const response = await axios.get('module/auth/users/list');
      if (response.status === 200) {
        setUserOptions(response?.data?.data?.users);
      }
    }
    catch (err) {
      console.log(err)
    }
  }

  const handleTextChange = (e) => {
    setTitle(e.target.value)
  }

  const handleTextChange2 = (e) => {
    setTitle2(e.target.value)
  }

  const handleuser = async (e) => {
    const id = e.target.value
    // alert(id)
    setUserId1(id)
  }

  const addListingApi = async () => {
    const data = {
      name: title,
      desc: title2,
      userId: userId1,
      progressPercentage: 30,
    }
    try {
      const res = await axios.post('module/listing/info/', data)
      if (res.status === 200) {
        GenerateToastConfig("Details Added Successfully", 'success');
        setAddListing(false)
        fetchData();
      }
      else {
        alert('error')
      }
    }
    catch (err) {
      alert(err)
    }
  }
  // newValue

  const fetchData = async () => {
    setIsLoading(true);
    const params = {};
    if (bedRoom > 0) {
      params.bedRoom = bedRoom;
    }
    if (bathRoom > 0) {
      params.bathRoom = bathRoom;
    }
    if (filterName.length !== 0) {
      params.search = filterName;
    }
    if (selectedName.length !== 0) {
      params.amenities = `[${selectedName}]`;
    }
    if (selectedStatus !== '') {
      params.list = selectedStatus;
    }

    try {
      let url = `module/listing/all?_page=${page}&_limit=${rowsPerPage}`;
      // if (search) {
      //   url += `&search=${search}`;
      //   setPage(1);
      // }
      if (search) url += `&search=${search}`;
      Object.entries(filters).forEach(([key, value]) => {
        if (value) url += `&${key}=${value}`;
      });

      const res = await axios.get(url, { params });
      if (res.status === 200) {
        setUserList(res.data.data.listingData);
        setTotalCount(res.data.data.totalCount);
      } else {
        GenerateToastConfig(res.data.message);
      }
    } catch (err) {
      GenerateToastConfig(err?.response?.data?.message);
    } finally {
      setIsLoading(false);
    }
  };

  useEffect(() => {
    fetchData();
  }, [page, rowsPerPage, filterName, order, orderBy, search, selectedStatus, selectedName, bathRoom, bedRoom, filters]);

  useEffect(() => {
    verifiedUser()
  }, [])

  useEffect(() => {
    updateUrlParams({ page, limit: rowsPerPage });
  }, [page, rowsPerPage, search]);

  const handleOpenMenu = () => {
    setOpen(true);
  };

  const handleOpenMenu2 = async () => {

    try {
      const res = await axios.get(`module/listing/amenities`);
      if (res.status === 200) {
        setGetAmenities(res.data.data.amenities);
        setOpen2(true);
      } else {
        GenerateToastConfig(res.data.message);
      }
    } catch (err) {
      GenerateToastConfig(err?.response?.data?.message);
    }
  };

  const handleOpenMenu3 = () => {
    setPage(1);
    setOpen3(true);
  };

  const handleCloseMenu = () => {
    setOpen(false);
  };
  const handleCloseMenu2 = () => {
    setOpen2(false);
  };
  const handleCloseMenu3 = () => {
    setOpen3(false);
  };

  const handleRequestSort = (event, property) => {
    const isAsc = orderBy === property && order === 'asc';
    setOrder(isAsc ? 'desc' : 'asc');
    setOrderBy(property);
  };

  const handleSelectAllClick = (event) => {
    if (event.target.checked) {
      const newSelecteds = userList.map((n) => n.name);
      setSelected(newSelecteds);
      return;
    }
    setSelected([]);
  };

  const declinelistingsmodel = (ids) => {
    sessionStorage.setItem('approveId', ids);
    setOpenApprove(true);
  };

  const approvelistings = async (ids) => {
    try {
      const res = await axios.post(`module/listing/status/${ids}`, {
        status: 'approve',
        reason: reason || '',
      });
      if (res.status === 200) {
        GenerateToastConfig(res.data.message, 'success');
        fetchData();
      } else {
        GenerateToastConfig(res.data.message);
      }
    } catch (err) {
      GenerateToastConfig(err?.response?.data?.message);
    }
  };

  const declinelistings = async () => {
    const ids = sessionStorage.getItem('approveId');
    try {
      const res = await axios.post(`module/listing/status/${ids}`, {
        status: 'decline',
        reason: reason || '',
      });
      if (res.status === 200) {
        GenerateToastConfig(res.data.message, 'success');
        fetchData();
        setOpenApprove(false);
      } else {
        GenerateToastConfig(res.data.message);
      }
    } catch (err) {
      GenerateToastConfig(err?.response?.data?.message);
    }
  };

  const deleteListings = async () => {
    try {
      const res = await axios.delete(`module/listing/delete/${rowId}`, {
        data: {
          userId,
        },
      });
      if (res.status === 200) {
        GenerateToastConfig(res.data.message, 'info');
        fetchData();
        setOpens(false);
        setUserId('')
        setRowId('')
      } else {
        GenerateToastConfig(res.data.message);
      }
    } catch (err) {
      GenerateToastConfig(err?.response?.data?.message);
    }
  };

  const bedIncrement = () => {
    // debugger
    setFilterBedRoom((prev) => parseInt(prev, 10) + 1);
  };

  const bathIncrement = () => {
    setFilterBathRoom((prev) => parseInt(prev, 10) + 1);
  };

  const bedDecrement = () => {
    if (filterbedRoom > 0) {
      setFilterBedRoom((prev) => parseInt(prev, 10) - 1);
    }
  };

  const bathDecrement = () => {
    if (filterbathRoom > 0) {
      setFilterBathRoom((prev) => parseInt(prev, 10) - 1);
    }
  };

  const clearRoomdata = () => {
    setBedRoom(0);
    setBathRoom(0);
    setFilterBedRoom(0);
    setFilterBathRoom(0);
  };

  const deSelect = () => {
    setSelectedName([]);
    setFilterAmenity([])
  };

  const clearStatus = () => {
    setSelectedStatus("");
    setFilterStatus("");
  };

  const setParamValue = () => {
    setBathRoom(filterbathRoom)
    setBedRoom(filterbedRoom)
    setOpen(false);
  };

  const setAmenityValue = () => {
    setSelectedName(filterAmenity)
    setOpen2(false);
  };

  const setStatusValue = () => {
    setOpen3(false);
    setSelectedStatus(filterStatus)
  };

  // const deletemodel = (id, userid) => {
  //   setOpens(true);
  //   setRowId(id)
  //   setUserId(userid)
  // };

  const navigation = (id) => {
    const searchParams = new URLSearchParams(location.search);
    const selectedTab = searchParams.get('tab') || 'published';
    navigate(`/dashboard/editlisting?id=${id}&tab=${selectedTab}`);
  }
  const handleOnChecked = (evt) => {
    if (evt.checked) {
      const newStatus = evt.value;
      setFilterStatus(newStatus);
    } else {
      setFilterStatus('');
    }
  };

  const handleChecked = (evt) => {
    if (evt.checked) {
      const newSelected = [...filterAmenity, evt.value];
      setFilterAmenity(newSelected);
    } else {
      setFilterAmenity(filterAmenity.filter((item) => item !== evt.value));
    }
  };

  const handleChangePage = (event, newpage) => {
    setPage(newpage + 1);
  };

  const handleChangeRowsPerPage = (event) => {
    setPage(1);
    setRowsPerPage(parseInt(event.target.value, 10));
  };

  const handleFilterByName = (event) => {
    setPage(1);
    setFilterName(event.target.value.trimStart());
  };

  function encryptCategory(category) {
    let sanitizedCategory = category?.toLowerCase();
    sanitizedCategory = sanitizedCategory?.replace(/ /g, '-');
    sanitizedCategory = sanitizedCategory?.replace(/[^a-zA-Z0-9_-]/g, '');
    sanitizedCategory = sanitizedCategory?.replace(/[_-]+/g, '-');
    sanitizedCategory = sanitizedCategory?.replace(/^[_-]+|[_-]+$/g, '');
    sanitizedCategory = sanitizedCategory?.substring(0, 100);
    return sanitizedCategory;
  }
  function encryptProduct(productName) {
    let sanitizedProductName = productName?.toLowerCase();
    sanitizedProductName = sanitizedProductName?.replace(/ /g, '-');
    sanitizedProductName = sanitizedProductName?.replace(/[^a-zA-Z0-9_-]/g, '');
    sanitizedProductName = sanitizedProductName?.replace(/[_-]+/g, '-');
    sanitizedProductName = sanitizedProductName?.replace(/^[_-]+|[_-]+$/g, '');
    sanitizedProductName = sanitizedProductName?.substring(0, 100);
    return sanitizedProductName;
  }
  const handleRoute = async (row) => {
    const categoryName = await encryptCategory(row?.propertyCategoryName?.category);
    const productName = await encryptProduct(row?.propertyName);
    const id = `${productName}_${row._id}`;

    const encodedCategoryName = encodeURIComponent(categoryName);
    const encodedId = encodeURIComponent(id);
    const url = `${APP_URL}/${'c'}/${encodedCategoryName}/${encodedId}?viewBy=admin`;
    // debugger
    window.open(url);
  }

  const handleCommission = (id, name) => {
    navigate('/dashboard/Commission&Tax', { state: { id, name } })
  }

  const ActionComponent = (cell) => {
    const original = cell?.row?.original
    const value = cell?.getValue()
    const [anchorEl, setAnchorEl] = useState(null);
    const [menuRowId, setMenuRowId] = useState(null);

    const handleActionMenu = (event, rowId) => {
      setAnchorEl(event.currentTarget);
      setMenuRowId(rowId);
    };

    const handleActionMenuClose = () => {
      setAnchorEl(null);
      setMenuRowId(null);
    };

    const deletemodel = (id, userid) => {
      setOpens(true);
      setRowId(id)
      setUserId(userid)
      setAnchorEl(null);
      setMenuRowId(null);
    };

    const approvelistings = async (ids) => {
      try {
        const res = await axios.post(`module/listing/status/${ids}`, {
          status: 'approve',
          reason: reason || '',
        });
        if (res.status === 200) {
          GenerateToastConfig(res.data.message, 'success');
          fetchData();
        } else {
          GenerateToastConfig(res.data.message);
        }
      } catch (err) {
        GenerateToastConfig(err?.response?.data?.message);
      }
    };

    const declinelistingsmodel = (ids) => {
      sessionStorage.setItem('approveId', ids);
      setOpenApprove(true);
    };

    return (
      <>
        <IconButton
          sx={{
            width: '37px',
            height: '37px',
            background: '#EBEBEB',
            color: 'black',
            display: 'flex',
            alignItems: 'center',
            justifyContent: 'center',
            borderRadius: '50%',
          }}
          onClick={(event) => handleActionMenu(event, value)}
        >
          <Iconify icon="mdi:dots-horizontal" />
        </IconButton>
        <Popover
          anchorEl={anchorEl}
          open={Boolean(anchorEl) && menuRowId === value}
          onClose={handleActionMenuClose}
          anchorOrigin={{ vertical: 'top', horizontal: 'left' }}
          transformOrigin={{ vertical: 'top', horizontal: 'right' }}
          PaperProps={{
            sx: { width: 140 },
          }}
        >

          {original?.status === 'approve' && (
            <MenuItem onClick={() => handleRoute(original)}>
              <Iconify icon={'carbon:view'} sx={{ mr: 2 }} /> View
            </MenuItem>
          )}

          <MenuItem onClick={() => navigation(original?._id)}>
            <Iconify icon={'carbon:edit'} sx={{ mr: 2 }} /> Edit
          </MenuItem>

          {(original?.status === 'publish' || original?.status === 'decline') && (
            <MenuItem onClick={() => approvelistings(original?._id)}>
              <Iconify icon={'mdi:approve'} sx={{ mr: 2 }} /> Approve
            </MenuItem>
          )}

          {original?.status === 'approve' && (
            <MenuItem onClick={() => declinelistingsmodel(original?._id)}>
              <Decline /> <span style={{ marginLeft: '16px' }}>Decline</span>
            </MenuItem>
          )}
          <MenuItem onClick={() => deletemodel(original?._id, original?.userData?._id)} sx={{ color: 'error.main' }}>
            <Iconify icon={'eva:trash-2-outline'} sx={{ mr: 2 }} /> Delete
          </MenuItem>
        </Popover>
      </>
    );

  }

  const columns = [
    {
      header: i18?.LISTINGPAGE?.PROPERTY_NAME || 'Property Name',
      accessorKey: "propertyName",
      id: "propertyName",
      showFilter: true,
      // cell: ({ row }) => <span>{row?.original?.propertyName || '---'}</span>,
    },
    {
      header: i18?.ACCOUNTSTITLE?.FULL_NAME || "Full Name",
      id: "firstname",
      accessorKey: "userName",
      showFilter: true,
      cell: ({ row }) => {
        const fullName = `${row.original?.userData?.firstname || ''} ${row.original?.userData?.lastname || ''}`.trim();
        return <span>{fullName || '---'}</span>;
      },
    },
    {
      header: i18?.LISTINGPAGE?.CITY || 'City',
      accessorKey: "city",
      id: "city",
      showFilter: true,
      cell: ({ row }) => <span>{row?.original?.address?.city || '---'}</span>,
    },
    {
      header: i18?.LISTINGPAGE?.STATE || 'State',
      accessorKey: "state",
      id: "state",
      showFilter: true,
      cell: ({ row }) => <span>{row?.original?.address?.state || '---'}</span>,
    },
    {
      header: i18?.LISTINGPAGE?.COUNTRY || 'Country',
      accessorKey: "country",
      id: "country",
      showFilter: true,
      cell: ({ row }) => <span>{row?.original?.address?.country || '---'}</span>,
    },
    {
      header: i18?.LISTINGPAGE?.PUBLISH || 'Publish',
      accessorKey: "Publish",
      id: "Publish",
      showFilter: false,
      cell: ({ row: { original } }) => (
        <Label color={original?.status === "pending" ? "error" : "success"}>
          {original?.status === "pending" ? "No" : "Yes"}
        </Label>
      )
    },
    {
      header: i18?.LISTINGPAGE?.STATUS || 'Status',
      accessorKey: "Status",
      id: "Status",
      showFilter: false,
      cell: ({ row: { original } }) =>
        <Label color={original?.status === "approve" ? "success" : "warning"}>{original?.status}</Label>
    },
    {
      header: i18?.LISTINGPAGE?.ACTION || 'Action',
      accessorKey: "_id",
      id: "action",
      cell: ActionComponent
    },
  ];

  const handleFilterChange = (filterKey, value) => {
    setFilters((prev) => ({ ...prev, [filterKey]: value }));
    setPage(1);
  };

  return (
    <>
      <Helmet>
        <title> Listings | Admin panel </title>
      </Helmet>

      {isMobile && <Stack direction="row" alignItems="center" style={{ marginBottom: '30px' }} justifyContent="space-between">
        <Typography variant="h4" gutterBottom>
          {i18?.LISTINGPAGE?.LISTING || "Listing"}
        </Typography>
        <Button variant="contained" onClick={() => setAddListing(true)}>
          {i18?.LISTINGPAGE?.ADD_LISTINGS || "Add Listings"}
        </Button>
      </Stack>}

      {!isMobile && <Stack direction="row" alignItems="center" justifyContent="space-between" mb={0}>
        <Typography variant="h4" gutterBottom>
          {i18?.LISTINGPAGE?.LISTING || "Listing"}
        </Typography>
        <Stack direction="row" alignItems="center" >
          <UserListToolbar
            filterName={filterName}
            onFilterName={handleFilterByName}
            search={search}
            setsearch={setsearch}
          />
          <Button variant="contained" onClick={() => setAddListing(true)}>
            {i18?.LISTINGPAGE?.ADD_LISTINGS || "Add Listings"}
          </Button>
        </Stack>
      </Stack>}

      {/* <Card sx={{ padding: '20px 0px', margin: '0px 0px', }}> */}
      <Stack direction="row" justifyContent="space-between" alignItems="center" sx={{ paddingRight: '0px' }} mb={3}>
        {isMobile && <UserListToolbar
          filterName={filterName}
          onFilterName={handleFilterByName}
          search={search}
          setsearch={setsearch}
        />}
        <div>
          {""}
        </div>
        <div style={{ display: 'flex', gap: '10px', marginRight: '10px', }}>
          {isMobile ? (
            <>
              <IconButton onClick={handleMenuOpen}>
                <MoreVertIcon />
              </IconButton>
              <Menu
                anchorEl={anchorEl}
                open={Boolean(anchorEl)}
                onClose={handleMenuClose}
              >
                <MenuItem onClick={() => { handleOpenMenu(); handleMenuClose(); }}>
                  {i18?.LISTINGPAGE?.ROOMS_AND_BEDS || "Area and Spaaace"}
                </MenuItem>
                <MenuItem onClick={() => { handleOpenMenu2(); handleMenuClose(); }}>
                  {i18?.LISTINGPAGE?.AMENITIES || "Amenities"}
                </MenuItem>
                <MenuItem onClick={() => { handleOpenMenu3(); handleMenuClose(); }}>
                  {i18?.LISTINGPAGE?.LISTING_STATUS || "Listing Status"}
                </MenuItem>
              </Menu>
            </>
          ) : (
            <>
              <Button variant="contained" onClick={handleOpenMenu}>
                {i18?.LISTINGPAGE?.ROOMS_AND_BEDS || "Area and Space"}
              </Button>
              <Badge
                color="secondary"
                variant="dot"
                invisible={selected.length === 0}
                sx={{
                  '& .MuiBadge-badge': {
                    backgroundColor: 'red'
                  }
                }}
              >
                <Button variant="contained" onClick={handleOpenMenu2}>
                  {i18?.LISTINGPAGE?.AMENITIES || "Amenities"}
                </Button>
              </Badge>
              <Button variant="contained" onClick={handleOpenMenu3}>
                {i18?.LISTINGPAGE?.LISTING_STATUS || "Listing Status"}
              </Button>
            </>
          )}
        </div>
      </Stack>

      <Scrollbar>
        <TanstackTableV8
          data={userList}
          columns={columns}
          filters={filters}
          isLoading={isLoading}
          onFilterChange={handleFilterChange}
        />
      </Scrollbar>


      {/* </Card> */}
      <TablePagination
        rowsPerPageOptions={[5, 10, 25]}
        component="div"
        count={totalCount || '0'}
        rowsPerPage={rowsPerPage}
        page={page - 1}
        onPageChange={handleChangePage}
        onRowsPerPageChange={handleChangeRowsPerPage}
        sx={{
          '.MuiTablePagination-selectLabel': {
            marginTop: '12px',
          },
          '.MuiTablePagination-displayedRows': {
            marginTop: '12px',
          },
          '.MuiTablePagination-actions': {
            marginBottom: '6px',
          }
        }}
      />
      <Popover
        open={Boolean(open)}
        onClose={handleCloseMenu}
        anchorReference="anchorPosition"
        anchorPosition={{ top: 170, left: 1300 }}
        anchorOrigin={{ vertical: 'bottom', horizontal: 'center' }}
        transformOrigin={{ vertical: 'top', horizontal: 'center' }}
        PaperProps={{
          sx: {
            p: 2,
            width: { xs: '90%', sm: 'auto' },
            '& .MuiMenuItem-root': {
              px: 1,
              typography: 'body2',
              borderRadius: 0.75,
            },
          },
        }}
      >
        <Grid container spacing={2} justifyContent="center" alignItems="center">
          <Grid item xs={12} sm={3}>
            <Typography>{i18?.LISTINGPAGE?.BEDROOM || "Area"}</Typography>
          </Grid>
          <Grid item xs={3}>
            <Button onClick={bedDecrement}>
              <Iconify icon={'zondicons:minus-outline'} />
            </Button>
          </Grid>
          <Grid item xs m={0}>
            <Typography align="center">{filterbedRoom}</Typography>
          </Grid>
          <Grid item xs={3}>
            <Button sx={{ color: 'error.main' }} onClick={bedIncrement}>
              <Iconify icon={'simple-line-icons:plus'} />
            </Button>
          </Grid>
        </Grid>
        <Grid container spacing={2} justifyContent="center" alignItems="center">
          <Grid item xs={12} sm={3}>
            <Typography>{i18?.LISTINGPAGE?.BATHROOM || "Space"}</Typography>
          </Grid>
          <Grid item xs={3}>
            <Button onClick={bathDecrement}>
              <Iconify icon={'zondicons:minus-outline'} />
            </Button>
          </Grid>
          <Grid item xs m={0}>
            <Typography align="center">{filterbathRoom}</Typography>
          </Grid>
          <Grid item xs={3}>
            <Button sx={{ color: 'error.main' }} onClick={bathIncrement}>
              <Iconify icon={'simple-line-icons:plus'} />
            </Button>
          </Grid>
        </Grid>
        <Grid container spacing={2} justifyContent="center" alignItems="center">
          <Grid item xs={6}>
            <Button sx={{ color: 'error.main' }} onClick={clearRoomdata} fullWidth>
              {i18?.LISTINGPAGE?.CLEAR || "Clear"}
            </Button>
          </Grid>
          <Grid item xs={6}>
            <Button onClick={() => setParamValue()} fullWidth>
              {i18?.LISTINGPAGE?.APPLY || "Apply"}
            </Button>
          </Grid>
        </Grid>
      </Popover>


      <Popover
        open={Boolean(open2)}
        onClose={handleCloseMenu2}
        anchorReference="anchorPosition"
        anchorPosition={{ top: 170, left: 1440 }}
        anchorOrigin={{ vertical: 'bottom', horizontal: 'center' }}
        transformOrigin={{ vertical: 'top', horizontal: 'center' }}
        PaperProps={{
          sx: {
            p: 2,
            width: 'auto',
            '& .MuiMenuItem-root': {
              px: 1,
              typography: 'body2',
              borderRadius: 0.75,
            },
          },
        }}
      >
        <div style={{ display: 'grid', gridTemplateColumns: 'auto auto auto', gap: '10px' }}>
          {Array.isArray(getAmenities) && getAmenities.map((items, index) => (
            <Grid key={index} container alignItems="center">
              <Checkbox
                checked={filterAmenity.includes(items._id)}
                value={items._id}
                onChange={(e) => handleChecked(e.target)}
              />
              <div style={{ width: "30px", height: "30px", marginLeft: "0" }}>
                <img src={IMAGE_URL + items.icon} alt='svg' />
              </div>
              <p style={{ margin: 0, marginLeft: '5px' }}>{items.name}</p>

            </Grid>
          ))
          }
        </div>
        <Grid container spacing={2} justifyContent="space-around" alignItems="center">
          <Grid item xs m={0}>
            <Button sx={{ color: 'error.main' }} onClick={deSelect}>
              {i18?.LISTINGPAGE?.CLEAR || "Clear"}
            </Button>
          </Grid>
          <Grid item xs m={0} p={0}>
            <Button sx={{ marginLeft: '20px' }} onClick={() => setAmenityValue()}>
              {i18?.LISTINGPAGE?.APPLY || "Apply"}
            </Button>
          </Grid>
        </Grid>
      </Popover>

      <Popover
        open={Boolean(open3)}
        onClose={handleCloseMenu3}
        anchorReference="anchorPosition"
        anchorPosition={{ top: 170, left: 1690 }}
        anchorOrigin={{ vertical: 'bottom', horizontal: 'center' }}
        transformOrigin={{ vertical: 'top', horizontal: 'center' }}
        PaperProps={{
          sx: {
            p: 2,
            width: { xs: '90%', sm: 'auto' },
            '& .MuiMenuItem-root': {
              px: 1,
              typography: 'body2',
              borderRadius: 0.75,
            },
          },
        }}
      >
        <Grid container spacing={2} justifyContent="center" alignItems="center">
          <Grid item xs={12} sm={12}>
            <Typography>
              <Checkbox
                checked={filterStatus.includes('listed')}
                value="listed"
                onChange={(e) => handleOnChecked(e.target)}
              />{' '}
              {i18?.LISTINGPAGE?.LISTED || "Listed"}
            </Typography>
            <Typography>
              <Checkbox
                checked={filterStatus.includes('unListed')}
                value="unListed"
                onChange={(e) => handleOnChecked(e.target)}
              />{' '}
              {i18?.LISTINGPAGE?.UNLISTED || "UnListed"}
            </Typography>
            <Typography>
              <Checkbox
                checked={filterStatus.includes('inProgress')}
                value="inProgress"
                onChange={(e) => handleOnChecked(e.target)}
              />{' '}
              {i18?.LISTINGPAGE?.INPROGRESS || "InProgress"}
            </Typography>
            <Typography>
              <Checkbox
                checked={filterStatus.includes('incomplete')}
                value="incomplete"
                onChange={(e) => handleOnChecked(e.target)}
              />{' '}
              {i18?.LISTINGPAGE?.INCOMPLETE || "InComplete"}
            </Typography>
          </Grid>
        </Grid>
        <Grid container spacing={2} justifyContent="space-between" alignItems="center" sx={{ marginTop: 2 }}>
          <Grid item xs={6}>
            <Button fullWidth sx={{ color: 'error.main' }} onClick={clearStatus}>
              {i18?.LISTINGPAGE?.CLEAR || "Clear"}
            </Button>
          </Grid>
          <Grid item xs={6}>
            <Button fullWidth onClick={() => setStatusValue()}>
              {i18?.LISTINGPAGE?.APPLY || "Apply"}
            </Button>
          </Grid>
        </Grid>
      </Popover>

      <DeleteModal
        isDeleteOpen={opens}
        handleClose={() => setOpens(false)}
        handleDelete={deleteListings}
      />

      <Modal
        open={openApprove}
        onClose={() => setOpenApprove(false)}
        aria-labelledby="modal-modal-title"
        aria-describedby="modal-modal-description"
      >
        <Box sx={style11}>
          <Grid item xs={6} sx={{ padding: '0px 5px' }}>
            <InputField
              label={i18?.LISTINGPAGE?.REASON || "Reason"}
              sx={{ margin: '10px 0px', width: '100%' }}
              name="desc"
              onChange={(e) => setReason(e.target.value)}
            />
          </Grid>

          <div className="d-flex justify-content-around mt-3">
            <Button variant="contained" size="medium" color="secondary" onClick={() => setOpenApprove(false)}>
              {i18?.LISTINGPAGE?.NO || "No"}
            </Button>
            <Button variant="contained" size="medium" color="primary" onClick={() => declinelistings()}>
              {i18?.LISTINGPAGE?.YES || "Yes"}
            </Button>
          </div>
        </Box>
      </Modal>

      <Modal
        open={addListing}
        onClose={() => setAddListing(false)}
        aria-labelledby="modal-modal-title"
        aria-describedby="modal-modal-description"
      >
        <Box sx={style11}>
          <>
            <IconButton
              onClick={() => setAddListing(false)}
              sx={{
                position: 'absolute',
                top: 16,
                right: 16,
                height: '25px',
                width: '25px',
                color: '#2B3343',
                display: 'flex',
                alignItems: 'center',
                justifyContent: 'center',
                boxShadow: "2px 2px 5px 0px #00000040",
                borderRadius: '50%',
              }}
            >
              <Box
                sx={{
                  width: '20px',
                  height: '20px',
                  display: 'flex',
                  alignItems: 'center',
                  justifyContent: 'center',
                }}
              >
                <Iconify icon="eva:close-fill" style={{ fontSize: 'inherit' }} onClose={() => setAddListing(false)} />
              </Box>
            </IconButton>
            <Typography
              variant="h5"
              sx={{
                mt: 0.5,
                display: 'flex',
                alignItems: 'center',
                fontSize: '20px',
                marginBottom: '10px',
              }}
            >
              {i18?.LISTINGPAGE?.USER || 'User'}
            </Typography>
            <Select
              sx={{ width: '100%', marginBottom: '10px' }}
              onChange={handleuser}
            >
              {userOptions.map((category) => (
                <MenuItem key={category._id} value={category._id}>
                  <div
                    style={{
                      width: '100%',
                      display: 'flex',
                      flexDirection: 'row',
                      justifyContent: 'space-between',
                    }}
                  >
                    <p style={{ width: '200px' }}>{category?.firstname} - {category?.email}</p>
                  </div>
                </MenuItem>
              ))}
            </Select>
            <div>
              <Typography variant="h5" sx={{ marginTop: '20px' }}>
                {i18?.LISTINGPAGE?.LISTING_TITLE || 'Listing Title'}
              </Typography>
              <Typography variant="body2" sx={{ marginBottom: "10px" }}>
                {i18?.LISTINGPAGE?.SHORT_TITLE_DESCRIPTION || 'Short Title Description'}
              </Typography>
              <textarea
                rows={5}
                className="textArea"
                value={title}
                onChange={handleTextChange}
                placeholder="Enter text here..."
                style={{
                  width: '100%',
                  marginBottom: '20px',
                  padding: '8px',
                  borderRadius: '4px',
                  borderColor: '#ccc',
                  resize: 'none',
                }}
              />

              <Typography variant="h5">
                {i18?.LISTINGPAGE?.LISTING_DETAILS || 'Listing Details'}
              </Typography>
              <Typography variant="body2" sx={{ marginBottom: "10px" }}>
                {i18?.LISTINGPAGE?.PLACE_DESCRIPTION || 'Place Description'}
              </Typography>
              <textarea
                rows={5}
                className="textArea2"
                value={title2}
                onChange={handleTextChange2}
                placeholder="Enter text here..."
                style={{
                  width: '100%',
                  marginBottom: '20px',
                  padding: '8px',
                  borderRadius: '4px',
                  borderColor: '#ccc',
                  resize: 'none',
                }}
              />
            </div>
            <Button
              variant="contained"
              size="medium"
              color="primary"
              onClick={() => addListingApi()}
              disabled={title.length === 0 || title2.length === 0 || userId1.length === 0}
              sx={{
                width: '100%'
              }}
            >
              {i18?.LISTINGPAGE?.SUBMIT || 'Submit'}
            </Button>
          </>
        </Box>
      </Modal>
    </>
  );
}
