/* eslint-disable react/prop-types */
import React, { useEffect, useState } from 'react';
import { Helmet } from 'react-helmet-async';
import { useNavigate, useLocation } from 'react-router-dom';
import {
  Stack,
  Button,
  Popover,
  MenuItem,
  Typography,
  IconButton,
  TablePagination,
  Grid,
  Modal,
  Box,
} from '@mui/material';
import Decline from '../../components/icons/Decline';
import { axios } from '../../utils/axios';
import { APP_URL } from '../../utils/config';
import { updateUrlParams } from '../../utils/urlUtilis';
// components
import Label from '../../components/label';
import Iconify from '../../components/iconify';
import Scrollbar from '../../components/scrollbar';
// sections
import { UserListToolbar } from '../../sections/@dashboard/user';
import "../page.scss"
import { useMyContext } from '../provider';
import GenerateToastConfig from '../../components/toast-config/GenerateToastConfig';
import useResponsive from '../../hooks/useResponsive';
import DeleteModal from '../../components/deleteModal/DeleteModal';
import InputField from '../../components/input/inputField';
import TanstackTableV8 from '../../components/tanstackMUItable/tanstackTableV8';

export default function DraftedListing() {
  const location = useLocation();
  const queryParams = new URLSearchParams(location.search)

  const navigate = useNavigate();
  const [search, setsearch] = useState('');
  const [opens, setOpens] = useState(false);
  const [openApprove, setOpenApprove] = useState(false);
  const [page, setPage] = useState(parseInt(queryParams.get('page'), 10) || 1);
  const [filterName, setFilterName] = useState('');
  const [rowsPerPage, setRowsPerPage] = useState(parseInt(queryParams.get('limit'), 10) || 10);
  const [userList, setUserList] = useState([]);
  const [totalCount, setTotalCount] = useState('');
  const [reason, setReason] = useState('');
  const [rowId, setRowId] = useState('')
  const [userId, setUserId] = useState('')
  const { i18 } = useMyContext();
  const isMobile = useResponsive('down', 'sm')
  const [filters, setFilters] = useState({});
  const [isLoading, setIsLoading] = useState(true);


  const style11 = {
    position: 'absolute',
    top: '50%',
    left: '50%',
    transform: 'translate(-50%, -50%)',
    width: isMobile ? "90%" : 600,
    backgroundColor: 'white',
    borderRadius: '8px',
    boxShadow: '0px 4px 16px rgba(0, 0, 0, 0.2)',
    p: isMobile ? 2 : 4,
  };

  const fetchData = async () => {
    setIsLoading(true);
    const params = {};
    if (filterName.length !== 0) {
      params.search = filterName;
    }

    try {
      let url = `module/listing/all?_page=${page}&_limit=${rowsPerPage}&list=incomplete`;
      // if (search) {
      //   url += `&search=${search}`;
      //   setPage(1);
      // }
      if (search) url += `&search=${search}`;
      Object.entries(filters).forEach(([key, value]) => {
        if (value) url += `&${key}=${value}`;
      });

      const res = await axios.get(url, { params });
      if (res.status === 200) {
        setUserList(res.data.data.listingData);
        setTotalCount(res.data.data.totalCount);
      } else {
        GenerateToastConfig(res.data.message);
      }
    } catch (err) {
      GenerateToastConfig(err?.response?.data?.message);
    } finally {
      setIsLoading(false);
    }
  };

  useEffect(() => {
    fetchData();
  }, [page, rowsPerPage, filterName, search, filters]);

  useEffect(() => {
    updateUrlParams({ page, limit: rowsPerPage });
  }, [page, rowsPerPage, search]);

  const declinelistings = async () => {
    const ids = sessionStorage.getItem('approveId');
    try {
      const res = await axios.post(`module/listing/status/${ids}`, {
        status: 'decline',
        reason: reason || '',
      });
      if (res.status === 200) {
        GenerateToastConfig(res.data.message, 'success');
        fetchData();
        setOpenApprove(false);
      } else {
        GenerateToastConfig(res.data.message);
      }
    } catch (err) {
      GenerateToastConfig(err?.response?.data?.message);
    }
  };

  const deleteListings = async () => {
    try {
      const res = await axios.delete(`module/listing/delete/${rowId}`, {
        data: {
          userId,
        },
      });
      if (res.status === 200) {
        GenerateToastConfig(res.data.message, 'info');
        fetchData();
        setOpens(false);
        setUserId('')
        setRowId('')
      } else {
        GenerateToastConfig(res.data.message);
      }
    } catch (err) {
      GenerateToastConfig(err?.response?.data?.message);
    }
  };

  const navigation = (id) => {
    const searchParams = new URLSearchParams(location.search);
    const selectedTab = searchParams.get('tab') || 'published'
    navigate(`/dashboard/editlisting?id=${id}&tab=${selectedTab}`);
  }

  const handleChangePage = (event, newpage) => {
    setPage(newpage + 1);
  };

  const handleChangeRowsPerPage = (event) => {
    setPage(1);
    setRowsPerPage(parseInt(event.target.value, 10));
  };

  const handleFilterByName = (event) => {
    setPage(1);
    setFilterName(event.target.value.trimStart());
  };

  function encryptCategory(category) {
    let sanitizedCategory = category?.toLowerCase();
    sanitizedCategory = sanitizedCategory?.replace(/ /g, '-');
    sanitizedCategory = sanitizedCategory?.replace(/[^a-zA-Z0-9_-]/g, '');
    sanitizedCategory = sanitizedCategory?.replace(/[_-]+/g, '-');
    sanitizedCategory = sanitizedCategory?.replace(/^[_-]+|[_-]+$/g, '');
    sanitizedCategory = sanitizedCategory?.substring(0, 100);
    return sanitizedCategory;
  }
  function encryptProduct(productName) {
    let sanitizedProductName = productName?.toLowerCase();
    sanitizedProductName = sanitizedProductName?.replace(/ /g, '-');
    sanitizedProductName = sanitizedProductName?.replace(/[^a-zA-Z0-9_-]/g, '');
    sanitizedProductName = sanitizedProductName?.replace(/[_-]+/g, '-');
    sanitizedProductName = sanitizedProductName?.replace(/^[_-]+|[_-]+$/g, '');
    sanitizedProductName = sanitizedProductName?.substring(0, 100);
    return sanitizedProductName;
  }
  const handleRoute = async (row) => {
    const categoryName = await encryptCategory(row?.propertyCategoryName?.category);
    const productName = await encryptProduct(row?.propertyName);
    const id = `${productName}_${row._id}`;

    const encodedCategoryName = encodeURIComponent(categoryName);
    const encodedId = encodeURIComponent(id);
    const url = `${APP_URL}/${'c'}/${encodedCategoryName}/${encodedId}?viewBy=admin`;
    // debugger
    window.open(url);
  }

  const ActionComponent = (cell) => {
    const original = cell?.row?.original
    const value = cell?.getValue()
    const [anchorEl, setAnchorEl] = useState(null);
    const [menuRowId, setMenuRowId] = useState(null);

    const handleActionMenu = (event, rowId) => {
      setAnchorEl(event.currentTarget);
      setMenuRowId(rowId);
    };

    const handleActionMenuClose = () => {
      setAnchorEl(null);
      setMenuRowId(null);
    };

    const deletemodel = (id, userid) => {
      setOpens(true);
      setRowId(id)
      setUserId(userid)
      setAnchorEl(null);
      setMenuRowId(null);
    };

    const approvelistings = async (ids) => {
      try {
        const res = await axios.post(`module/listing/status/${ids}`, {
          status: 'approve',
          reason: reason || '',
        });
        if (res.status === 200) {
          GenerateToastConfig(res.data.message, 'success');
          fetchData();
        } else {
          GenerateToastConfig(res.data.message);
        }
      } catch (err) {
        GenerateToastConfig(err?.response?.data?.message);
      }
    };

    const declinelistingsmodel = (ids) => {
      sessionStorage.setItem('approveId', ids);
      setOpenApprove(true);
    };

    return (
      <>
        <IconButton
          sx={{
            width: '37px',
            height: '37px',
            background: '#EBEBEB',
            color: 'black',
            display: 'flex',
            alignItems: 'center',
            justifyContent: 'center',
            borderRadius: '50%',
          }}
          onClick={(event) => handleActionMenu(event, value)}
        >
          <Iconify icon="mdi:dots-horizontal" />
        </IconButton>
        <Popover
          anchorEl={anchorEl}
          open={Boolean(anchorEl) && menuRowId === value}
          onClose={handleActionMenuClose}
          anchorOrigin={{ vertical: 'top', horizontal: 'left' }}
          transformOrigin={{ vertical: 'top', horizontal: 'right' }}
          PaperProps={{
            sx: { width: 140 },
          }}
        >

          {original?.status === 'approve' && (
            <MenuItem onClick={() => handleRoute(original)}>
              <Iconify icon={'carbon:view'} sx={{ mr: 2 }} /> View
            </MenuItem>
          )}

          <MenuItem onClick={() => navigation(original?._id)}>
            <Iconify icon={'carbon:edit'} sx={{ mr: 2 }} /> Edit
          </MenuItem>

          {(original?.status === 'publish' || original?.status === 'decline') && (
            <MenuItem onClick={() => approvelistings(original?._id)}>
              <Iconify icon={'mdi:approve'} sx={{ mr: 2 }} /> Approve
            </MenuItem>
          )}

          {original?.status === 'approve' && (
            <MenuItem onClick={() => declinelistingsmodel(original?._id)}>
              <Decline /> <span style={{ marginLeft: '16px' }}>Decline</span>
            </MenuItem>
          )}
          <MenuItem onClick={() => deletemodel(original?._id, original?.userData?._id)} sx={{ color: 'error.main' }}>
            <Iconify icon={'eva:trash-2-outline'} sx={{ mr: 2 }} /> Delete
          </MenuItem>
        </Popover>
      </>
    );

  }

  const columns = [
    {
      header: i18?.LISTINGPAGE?.PROPERTY_NAME || 'Property Name',
      accessorKey: "propertyName",
      id: "propertyName",
      showFilter: true,
      // cell: ({ row }) => <span>{row?.original?.propertyName || '---'}</span>,
    },
    {
      header: i18?.ACCOUNTSTITLE?.FULL_NAME || "Full Name",
      id: "firstname",
      accessorKey: "userName",
      showFilter: true,
      cell: ({ row }) => {
        const fullName = `${row.original?.userData?.firstname || ''} ${row.original?.userData?.lastname || ''}`.trim();
        return <span>{fullName || '---'}</span>;
      },
    },
    {
      header: i18?.LISTINGPAGE?.CITY || 'City',
      accessorKey: "city",
      id: "city",
      showFilter: true,
      cell: ({ row }) => <span>{row?.original?.address?.city || '---'}</span>,
    },
    {
      header: i18?.LISTINGPAGE?.STATE || 'State',
      accessorKey: "state",
      id: "state",
      showFilter: true,
      cell: ({ row }) => <span>{row?.original?.address?.state || '---'}</span>,
    },
    {
      header: i18?.LISTINGPAGE?.COUNTRY || 'Country',
      accessorKey: "country",
      id: "country",
      showFilter: true,
      cell: ({ row }) => <span>{row?.original?.address?.country || '---'}</span>,
    },
    {
      header: i18?.LISTINGPAGE?.PUBLISH || 'Publish',
      accessorKey: "Publish",
      id: "Publish",
      showFilter: false,
      cell: ({ row: { original } }) => (
        <Label color={original?.status === "pending" ? "error" : "success"}>
          {original?.status === "pending" ? "No" : "Yes"}
        </Label>
      )
    },
    {
      header: i18?.LISTINGPAGE?.STATUS || 'Status',
      accessorKey: "Status",
      id: "Status",
      showFilter: false,
      cell: ({ row: { original } }) =>
        <Label color={original?.status === "approve" ? "success" : "warning"}>{original?.status}</Label>
    },
    {
      header: i18?.LISTINGPAGE?.ACTION || 'Action',
      accessorKey: "_id",
      id: "action",
      cell: ActionComponent
    },
  ];

  const handleFilterChange = (filterKey, value) => {
    setFilters((prev) => ({ ...prev, [filterKey]: value }));
    setPage(1);
  };

  return (
    <>
      <Helmet>
        <title> Drafted Listings </title>
      </Helmet>

      {isMobile && <Stack direction="row" alignItems="center" style={{ marginBottom: '30px' }} justifyContent="space-between">
        <Typography variant="h4" gutterBottom>
          {i18?.LISTINGPAGE?.DRAFTED_LISTING || "Drafted Listing"}
        </Typography>
      </Stack>}

      {!isMobile && <Stack direction="row" alignItems="center" justifyContent="space-between" mb={0}>
        <Typography variant="h4" gutterBottom>
          {i18?.LISTINGPAGE?.DRAFTED_LISTING || "Drafted Listing"}
        </Typography>
        <Stack direction="row" alignItems="center" >
          <UserListToolbar
            filterName={filterName}
            onFilterName={handleFilterByName}
            search={search}
            setsearch={setsearch}
          />
        </Stack>
      </Stack>}

      <Scrollbar>
        <TanstackTableV8
          data={userList}
          columns={columns}
          filters={filters}
          isLoading={isLoading}
          onFilterChange={handleFilterChange}
        />
      </Scrollbar>


      {/* </Card> */}
      <TablePagination
        rowsPerPageOptions={[5, 10, 25]}
        component="div"
        count={totalCount || '0'}
        rowsPerPage={rowsPerPage}
        page={page - 1}
        onPageChange={handleChangePage}
        onRowsPerPageChange={handleChangeRowsPerPage}
        sx={{
          '.MuiTablePagination-selectLabel': {
            marginTop: '12px',
          },
          '.MuiTablePagination-displayedRows': {
            marginTop: '12px',
          },
          '.MuiTablePagination-actions': {
            marginBottom: '6px',
          }
        }}
      />

      <DeleteModal
        isDeleteOpen={opens}
        handleClose={() => setOpens(false)}
        handleDelete={deleteListings}
      />

      <Modal
        open={openApprove}
        onClose={() => setOpenApprove(false)}
        aria-labelledby="modal-modal-title"
        aria-describedby="modal-modal-description"
      >
        <Box sx={style11}>
          <Grid item xs={6} sx={{ padding: '0px 5px' }}>
            <InputField
              label={i18?.LISTINGPAGE?.REASON || "Reason"}
              sx={{ margin: '10px 0px', width: '100%' }}
              name="desc"
              onChange={(e) => setReason(e.target.value)}
            />
          </Grid>

          <div className="d-flex justify-content-around mt-3">
            <Button variant="contained" size="medium" color="secondary" onClick={() => setOpenApprove(false)}>
              {i18?.LISTINGPAGE?.NO || "No"}
            </Button>
            <Button variant="contained" size="medium" color="primary" onClick={() => declinelistings()}>
              {i18?.LISTINGPAGE?.YES || "Yes"}
            </Button>
          </div>
        </Box>
      </Modal>
    </>
  );
}
